  52→            padding:12px 24px;font-size:14px;font-weight:600;white-space:nowrap;
  53→            opacity:0.7;cursor:default;display:flex;align-items:center;gap:4px;
  54→          "><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>Check</button>
  55→        </div>
  56→        <div style="
  57→          margin-top:16px;padding:14px 16px;border-radius:8px;
  58→          background:linear-gradient(135deg,#00806008,#00806014);border:1px solid #00806030;
  59→          font-size:14px;color:#008060;line-height:1.5;
  60→          display:flex;gap:12px;align-items:flex-start;
  61→        ">
  62→          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="width:22px;height:22px;flex-shrink:0;margin-top:1px"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><path d="M22 4L12 14.01l-3-3"/></svg>
  63→          <div>
  64→            Great news! We deliver to your area.
  65→            <div style="margin-top:6px;font-size:13px;opacity:0.85;display:flex;align-items:center;gap:6px;">
  66→              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:14px;height:14px"><path d="M1 3h15v13H1z"/><path d="M16 8h4l3 3v5h-7V8z"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
  67→              Estimated delivery: 2-3 business days
  68→            </div>
  69→          </div>
  70→        </div>
  71→        <p style="margin:14px 0 0;font-size:11px;color:#8c9196;text-align:center;">
  72→          Pinzo — live widget loads on your storefront
  73→        </p>
  74→      </div>
  75→    </div>
  76→  </div>
  77→  <script>
  78→  (function() {
  79→    var bid = "{{ block.id }}";
  80→    function check() {
  81→      if (window.__zccAppEnabled) {
  82→        var inactive = document.getElementById('zcc-inactive-' + bid);
  83→        var active = document.getElementById('zcc-active-' + bid);
  84→        if (inactive) inactive.style.display = 'none';
  85→        if (active) active.style.display = 'block';
  86→      }
  87→    }
  88→    check();
  89→    setTimeout(check, 500);
  90→    setTimeout(check, 1500);
  91→    setTimeout(check, 3000);
  92→  })();
  93→  </script>
  94→{% else %}
  95→
  96→<div
  97→  id="zcc-widget-{{ block.id }}"
  98→  data-zcc-widget="true"
  99→  data-shop="{{ shop.permanent_domain }}"
 100→  data-api="{{ app.url }}"
 101→  data-proxy="/apps/zipcheck"
 102→  data-block="{{ block.id }}"
 103→  {{ block.shopify_attributes }}
 104→></div>
 105→
 106→<script>
 107→(function () {
 108→  // Wait for app embed to set window.__zccAppEnabled.
 109→  // App embed (target: body) may load after this section block, so we poll briefly.
 110→  var maxWait = 3000; // ms
 111→  var interval = 50;  // ms
 112→  var elapsed = 0;
 113→
 114→  function tryInit() {
 115→    if (window.__zccAppEnabled) {
 116→      init();
 117→    } else if (elapsed < maxWait) {
 118→      elapsed += interval;
 119→      setTimeout(tryInit, interval);
 120→    }
 121→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
 122→  }
 123→
 124→  // Start checking — if already set, runs immediately
 125→  if (document.readyState === 'loading') {
 126→    document.addEventListener('DOMContentLoaded', tryInit);
 127→  } else {
 128→    tryInit();
 129→  }
 130→
 131→  function init() {
 132→  var ROOT_ID = "zcc-widget-{{ block.id }}";
 133→  var container = document.getElementById(ROOT_ID);
 134→  if (!container) return;
 135→
 136→  var SHOP = container.dataset.shop;
 137→  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
 138→  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
 139→  // fall back to the relative proxy path so the request still routes correctly through
 140→  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
 141→  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
 142→  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
 143→  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
 144→  // (which Shopify will forward to our app via the App Proxy config).
 145→  var API_BASE = (_rawApi && _rawApi.indexOf("http") === 0) ? _rawApi : _proxyPath;
 146→
 147→  // Always fetch fresh config from the API so color/setting changes made in the
 148→  // admin are reflected on the storefront immediately. The metafield-embedded
 149→  // data-config attribute is intentionally ignored here: it is baked into
 150→  // Shopify's CDN-cached HTML at render time and can be stale for many minutes
 151→  // after a merchant saves new settings. The API endpoint returns
 152→  // Cache-Control: no-store so it is always up to date.
 153→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
 154→    .then(function (r) {
 155→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
 156→      return r.json();
 157→    })
 158→    .then(function (cfg) { renderWidget(cfg); })
 159→    .catch(function (err) {
 160→      console.warn("[Pinzo] Could not load widget config, using defaults:", err.message || err);
 161→      renderWidget({});
 162→    });
 163→
 164→  function renderWidget(cfg) {
 165→    // Merge with defaults
 166→    var D = {
 167→      position: "inline",
 168→      heading: "Check Delivery Availability",
 169→      placeholder: "Enter your zip code",
 170→      buttonText: "Check",
 171→      successMessage: "Great news! We deliver to your area.",
 172→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
 173→      notFoundMessage: "We currently do not ship to this ZIP code.",
 174→      primaryColor: "#008060",
 175→      successColor: "#008060",
 176→      errorColor: "#D72C0D",
 177→      backgroundColor: "#FFFFFF",
 178→      textColor: "#202223",
 179→      borderRadius: "8",
 180→      showEta: true,
 181→      showZone: false,
 182→      showWaitlistOnFailure: false,
 183→      showCod: true,
 184→      showReturnPolicy: true,
 185→      showCutoffTime: true,
 186→      showDeliveryDays: true,
 187→      customCss: "",
 188→      blockCartOnInvalid: false,
 189→      showSocialProof: true,
 190→    };
 191→    Object.keys(D).forEach(function (k) {
 192→      if (cfg[k] === undefined || cfg[k] === null) cfg[k] = D[k];
 193→    });
 194→
 195→    var rad = cfg.borderRadius + "px";
 196→    var WID = "zcc-" + ROOT_ID;
 197→
 198→    if (cfg.position === "floating") {
 199→      renderFloating(cfg, WID, rad);
 200→    } else if (cfg.position === "popup") {
 201→      renderPopup(cfg, WID, rad);
 202→    } else {
 203→      renderInline(cfg, WID, rad);
 204→    }
 205→
 206→    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
 207→    // until the customer validates their ZIP code
 208→    if (cfg.blockCartOnInvalid) {
 209→      blockCartButtonsInitial();
 210→    }
 211→  }
 212→
 213→  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
 214→  function blockCartButtonsInitial() {
 215→    var ATC_SELECTORS = [
 216→      'button[name="add"]',
 217→      '.product-form__submit',
 218→      '[data-product-add]',
 219→      '.btn--add-to-cart',
 220→      '.product-form button[type="submit"]',
 221→      'button.shopify-payment-button__button',
 222→      '.shopify-payment-button button',
 223→      'button.product-form__cart-submit'
 224→    ].join(',');
 225→
 226→    function doBlock() {
 227→      try {
 228→        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
 229→        atcBtns.forEach(function(b) {
 230→          if (!b.closest('[data-zcc-widget]')) {
 231→            if (!b.getAttribute('data-zcc-blocked')) {
 232→              b.setAttribute('data-zcc-orig-title', b.title || '');
 233→            }
 234→            b.disabled = true;
 235→            b.style.opacity = '0.5';
 236→            b.title = 'Please check ZIP code availability first';
 237→            b.setAttribute('data-zcc-blocked', 'true');
 238→          }
 239→        });
 240→      } catch(e) {}
 241→    }
 242→
 243→    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
 244→    doBlock();
 245→    setTimeout(doBlock, 500);
 246→    setTimeout(doBlock, 1500);
 247→
 248→    // MutationObserver for dynamic payment buttons
 249→    if (typeof MutationObserver !== 'undefined') {
 250→      var observer = new MutationObserver(function() { doBlock(); });
 251→      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
 252→      if (form) {
 253→        observer.observe(form, { childList: true, subtree: true });
 254→        setTimeout(function() { observer.disconnect(); }, 10000);
 255→      }
 256→    }
 257→  }
 258→
 259→  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
 260→  function scopeCustomCss(rawCss, wid) {
 261→    if (!rawCss) return "";
 262→    // Strip </style> tags to prevent injection
 263→    var css = rawCss.replace(/<\/style>/gi, "");
 264→    var result = "";
 265→    var i = 0;
 266→    while (i < css.length) {
 267→      // Skip whitespace
 268→      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
 269→      if (i >= css.length) break;
 270→      // Pass through @keyframes and @font-face unchanged
 271→      if (css[i] === '@') {
 272→        var atRule = "";
 273→        var j = i;
 274→        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
 275→        var atName = atRule.trim().toLowerCase();
 276→        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
 277→          result += atRule;
 278→          if (j < css.length && css[j] === '{') {
 279→            var depth = 1; result += css[j]; j++;
 280→            while (j < css.length && depth > 0) {
 281→              if (css[j] === '{') depth++;
 282→              if (css[j] === '}') depth--;
 283→              result += css[j]; j++;
 284→            }
 285→          }
 286→          i = j; continue;
 287→        }
 288→        // @media: scope inner rules
 289→        if (atName.indexOf("@media") === 0) {
 290→          result += atRule;
 291→          if (j < css.length && css[j] === '{') {
 292→            result += '{'; j++;
 293→            // Collect inner content
 294→            var depth = 1; var inner = "";
 295→            while (j < css.length && depth > 0) {
 296→              if (css[j] === '{') depth++;
 297→              if (css[j] === '}') depth--;
 298→              if (depth > 0) inner += css[j];
 299→              j++;
 300→            }
 301→            result += scopeCustomCss(inner, wid);
 302→            result += '}';
 303→          }
 304→          i = j; continue;
 305→        }
 306→      }
 307→      // Regular rule: grab selector, prefix with #wid
 308→      var sel = ""; var body = "";
 309→      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
 310→      if (i < css.length) { i++; } // skip {
 311→      var depth = 1;
 312→      while (i < css.length && depth > 0) {
 313→        if (css[i] === '{') depth++;
 314→        if (css[i] === '}') depth--;
 315→        if (depth > 0) body += css[i];
 316→        i++;
 317→      }
 318→      if (sel.trim()) {
 319→        // Split multiple selectors by comma and prefix each
 320→        var selectors = sel.split(',').map(function(s) {
 321→          s = s.trim();
 322→          if (!s) return '';
 323→          return '#' + wid + ' ' + s;
 324→        }).filter(Boolean).join(', ');
 325→        result += selectors + ' {' + body + '}';
 326→      }
 327→    }
 328→    return result;
 329→  }
