 778→      wBtn.innerHTML = wBtnOriginalHtml;
 779→    }
 780→
 781→    fetch(API_BASE + "/api/waitlist", {
 782→      method: "POST",
 783→      headers: { "Content-Type": "application/json" },
 784→      body: JSON.stringify(payload),
